def is_simple_power(x, n):
    if n == 0:
        return x == 1
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    import math
    if n > 0:
        if x <= 0:
            return False
        try:
            exponent = math.log(x) / math.log(n)
        except ValueError:
            return False
    else:
        if x == 0:
            return False
        try:
            exponent = math.log(abs(x)) / math.log(abs(n))
        except ValueError:
            return False
    if abs(exponent - round(exponent)) > 1e-10:
        return False
    return n ** int(round(exponent)) == x
